ft_ing_pc_pobreza_monetaria.body:
{
    result <- ft_ing_total_pobreza_monetaria(tbl, ing_ext, remesas, .keep, .reuse)
    canonical <- ft_income_table(result, TRUE)
    ids <- ft_key_id(canonical, ft_keys[1:3])
    if ("EFT_ZONA" %in% names(result) && any(vapply(split(result$EFT_ZONA, ids), function(x) length(unique(x)) != 
        1L, logical(1)))) 
        stop("Zona inconsistente dentro del hogar.", call. = FALSE)
    result$ing_pc_pobreza_monetaria <- if (nrow(result)) 
        ave(result$ing_total_pobreza_monetaria, ids, FUN = function(x) mean(x, na.rm = FALSE))
    else numeric()
    result
}

