ft_ing_imputado_vivienda_propia.body:
{
    canonical <- ft_income_table(tbl, TRUE)
    ft_numeric(canonical, c("EFT_MONTO_PROBABLE_ALQ", "EFT_PARENTESCO_CON_JEFE"))
    ids <- ft_key_id(canonical, ft_keys[1:3])
    head <- canonical$EFT_PARENTESCO_CON_JEFE == 1
    if (anyNA(head) || any(vapply(split(head, ids), sum, numeric(1)) != 1)) 
        stop("Se requiere exactamente un jefe por hogar.", call. = FALSE)
    value <- if (nrow(canonical)) 
        ave(canonical$EFT_MONTO_PROBABLE_ALQ, ids, FUN = function(x) if (all(is.na(x))) 
            NA_real_
        else mean(x, na.rm = TRUE))
    else numeric()
    tbl$ing_imputado_vivienda_propia <- ifelse(head, value, 0)
    tbl
}

