ft_peri_vars.body:
{
    for (name in c("rm", "ano", "semestre", "periodo")) ft_check_flag(get(name), name)
    parts <- ft_period_parts(tbl)
    if (ano) 
        tbl$ano <- parts$ano
    if (semestre) 
        tbl$semestre <- parts$semestre
    if (periodo) 
        tbl$periodo <- parts$periodo
    if (rm) 
        tbl[[parts$column]] <- NULL
    tbl
}
